#include "mka/movie_service_host_clock.hpp"
#include <cstdio>
#include <fstream>
#include <stdexcept>
using namespace mka::video;
namespace {
void check(bool b,const char* t){if(!b)throw std::runtime_error(t);}
struct Input final:MoviePlaybackInput {
    RetailMovieRequest r;std::shared_ptr<const MovieSourceObservationIdentity> id;
    Input(RetailMovieRequest q,std::shared_ptr<const MovieSourceObservationIdentity> i):r(std::move(q)),id(std::move(i)){}
    const RetailMovieRequest& request()const noexcept override{return r;}
    std::shared_ptr<const MovieSourceObservationIdentity> observation_identity()const noexcept override{return id;}
    MovieReadResult next(MovieControlFailure& f)override{f={};MovieReadResult result;result.status=MovieReadStatus::end;return result;}
};
struct GPU final:NativeMovieGpuBackend {
    MovieGpuUpload upload(const MovieRgbaFrame&)override{throw std::runtime_error("no timing fixture upload");}
    MovieGpuSubmission present(const NativeMoviePresentPlan&,const MovieHostLayout&)override{throw std::runtime_error("no timing fixture present");}
    MovieFenceResult poll(const std::shared_ptr<MovieGpuFence>&)override{return {MovieFenceState::complete,MovieGpuError::none};}
    void retire(std::shared_ptr<MovieGpuFence>)noexcept override{}
};
struct Rig {
    std::unique_ptr<NativeMovieService> service;MovieServiceRequestIdentity identity;
    explicit Rig(const NativeMovieColorTable& color){
        auto token=std::make_shared<const MovieSourceObservationIdentity>();MovieServiceFailure f;
        service=NativeMovieService::create(1.0f,[](const RetailMovieRequest&,std::shared_ptr<const MovieSourceObservationIdentity>,const std::optional<mka::sound::AudioStreamFormat>&,MovieSessionFailure& why)->std::optional<MovieServicePolicyConfiguration>{why={};return MovieServicePolicyConfiguration{MoviePlaybackAudioPresence::absent,{},MovieFrameEligibilityConfig{3,1,0,0,MovieFrameEligibilityMode::direct},{3,1},MovieClockFilterConfig::source_defaults(),MovieNativeTargetRoute::published_position,MovieNativeCompletion::video,true,false,true,0,0,0,0,MovieOutputPositionProfile::successful_frame_no_repeat_no_skip};},
        [token,color](const RetailMovieRequest& r,std::int64_t,MovieSessionPolicyFactory factory,NativeMovieControlContext& context,MovieSessionFailure& why){auto policies=factory(r,token,std::nullopt,why);if(!policies)return std::unique_ptr<NativeMoviePlaybackSession>{};MoviePlaybackConfiguration c;c.audio=MoviePlaybackAudioPresence::absent;c.layout={1,640,448,MovieAspectMode::explicit_display_aspect,4,3,MovieWindowPolicy::centered_fit};c.filter=MovieFilter::nearest;c.queued_byte_budget=1024;return NativeMoviePlaybackSession::create_from_ports(std::make_unique<Input>(r,token),std::move(policies),{},std::make_shared<GPU>(),color,c,context,why);},f);
        check(service&&service->start(12,MovieViewSelection::normal,0,4,f),"real service/session/context start");auto id=service->request_identity(f);check(bool(id),"real request identity");identity=*id;
    }
    void ready(){MovieServiceFailure f;check(service->command(identity,MovieNativeCommand::owner_start,f)&&service->command(identity,MovieNativeCommand::video_start,f)&&service->poll(f).progress==MovieControlProgress::ongoing,"explicit fixture command acknowledgments cause actual Session unpause");}
};
}
int main(int argc,char** argv){try{
    check(argc==2,"usage: test_native_movie_service_host_clock original_MOVIER.ovl");std::ifstream file(std::filesystem::u8path(argv[1]),std::ios::binary);check(bool(file),"existing color source");std::vector<std::uint8_t> b((std::istreambuf_iterator<char>(file)),{});check(b.size()>=0x77dd8+6144,"color extent");MovieColorError ce;auto color=NativeMovieColorTable::decode(MovieColorRole::helper_default,b.data()+0x77dd8,6144,ce);check(bool(color),"existing color table");
    MovieServiceHostClockFailure failure;MovieHostClockFailure hf;MovieServiceFailure sf;std::int64_t ticks=0;
    {Rig r(*color);auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,10,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::elapsed_service,true,std::move(clock),failure);check(binding&&binding->begin(failure),"bind actual paused source");ticks=100;check(binding->update({},failure)&&r.service->snapshot(sf)->context->service.counter==0,"preparation pause excludes elapsed intervals");r.ready();check(binding->update({},failure),"actual unpause anchors new interval");for(ticks=101;ticks<=103;++ticks)check(binding->update({},failure),"fractional host update");check(r.service->snapshot(sf)->context->service.counter==0,"sub-count time retained without poll loss");ticks=104;check(binding->update({},failure)&&r.service->snapshot(sf)->context->service.counter==1,"cumulative projection crosses one service count");ticks=110;check(binding->update({},failure)&&r.service->snapshot(sf)->context->service.counter==3,"exact cumulative second across polls");check(r.service->close(sf)&&binding->update({},failure)&&binding->snapshot(failure)->stopped,"actual inactive retained lifecycle stops clock without EOF inference");}
    {Rig r(*color);r.ready();check(r.service->increment_service(r.identity,{INT64_MIN+1,3},sf),"actual Service APIs establish valid negative counter/retained baseline");ticks=0;auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,1,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::elapsed_service,true,std::move(clock),failure);check(binding->begin(failure),"wide cancellation source baseline begin");ticks=4611686018427387904LL;check(binding->update({},failure),"wide projected delta above int64 accepted atomically");auto state=r.service->snapshot(sf);check(state&&state->context->service.counter==4611686018427387905LL&&state->context->service.retained==4611686018427387904LL,"both counter and retained final destinations independently fit after wide cancellation");}
    {Rig r(*color);ticks=0;auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,10,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::elapsed_service,true,std::move(clock),failure);check(binding->begin(failure),"baseline fixture begin");check(r.service->increment_service(r.identity,{1,1},sf),"external baseline mutation");check(!binding->update({},failure)&&failure.kind==MovieServiceHostClockError::baseline_changed&&!r.service->snapshot(sf)->active,"baseline mismatch terminally cancels same request");}
    {Rig r(*color);ticks=0;auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,10,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::anchored_audio,true,std::move(clock),failure);check(binding->begin(failure),"audio explicit policy begin");check(!binding->update({},failure)&&failure.kind==MovieServiceHostClockError::unavailable&&!r.service->snapshot(sf)->active,"missing anchored audio never falls back to elapsed or padding");}
    {Rig r(*color);ticks=0;auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,10,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::anchored_audio,true,std::move(clock),failure);check(binding->begin(failure),"anchored fixture begin");MovieAnchoredAudioClockSample sample{r.identity.source_key,r.identity.source,std::make_shared<const MovieNativeAudioClockAnchor>(),{0,48000},true,true};check(binding->update(sample,failure)&&r.service->snapshot(sf)->context->cached_clock.has_value(),"explicit source-owned anchored sample feeds actual context filter");sample.elapsed={1,2};check(binding->update(sample,failure),"same anchored clock accepts changed positive denominator");sample.elapsed={2,3};check(binding->update(sample,failure),"rational elapsed ordering uses cross products across changing units");auto foreign=sample;foreign.source=std::make_shared<const MovieSourceObservationIdentity>();check(!binding->update(foreign,failure)&&failure.kind==MovieServiceHostClockError::foreign_source&&!r.service->snapshot(sf)->active,"foreign audio sample rejected with same-request cleanup");}
    {Rig r(*color);ticks=0;auto clock=NativeMovieHostClock::create_with_reader(r.identity.source_key,r.identity.source,10,[&]{return std::optional<std::int64_t>{ticks};},hf);auto binding=NativeMovieServiceHostClock::create_with_clock(*r.service,r.identity,MovieServiceHostClockPolicy::anchored_audio,true,std::move(clock),failure);check(binding->begin(failure),"rational regression fixture begin");MovieAnchoredAudioClockSample sample{r.identity.source_key,r.identity.source,std::make_shared<const MovieNativeAudioClockAnchor>(),{2,3},true,true};check(binding->update(sample,failure),"actual explicit first rational sample");sample.elapsed={1,2};check(!binding->update(sample,failure)&&failure.kind==MovieServiceHostClockError::regression&&!r.service->snapshot(sf)->active,"actual rational regression rejects even with a changed positive denominator");}
    check(std::puts("PASS native service host timing binding cumulative elapsed/explicit audio; no master-policy or output anchor admission")>=0&&std::fflush(stdout)==0,"checked footer");return 0;
}catch(const std::exception& e){std::fprintf(stderr,"FAIL service host clock %s\n",e.what());return 1;}}
